<script setup lang="ts">
import PufferMark from './PufferMark.vue';
import QR from 'qrcode/lib/core/qrcode';
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import {memberApi,getServiceBase,assetUrl,captureMemberContext} from '@/services/api';
import CaptchaField from './CaptchaField.vue';
import {applicationApi,type CaptchaInput} from '@/services/application';
import {applicationRuntime} from '@/services/application-runtime';
import {getHistoryScope} from '@/services/library';
const props=defineProps<{demo?:boolean;accountOnly?:boolean}>();const profile=ref<any>(null),plans=ref<any[]>([]),orders=ref<any[]>([]),username=ref(''),password=ref(''),password2=ref(''),register=ref(false),busy=ref(false),message=ref(''),mode=ref('account'),config=ref<any>({}),payUrl=ref(''),pending=ref<any>(null),payMethod=ref('alipay'),qrRows=ref<boolean[][]>([]),amount=ref(10),period=ref('month');
const emit=defineEmits<{profile:[value:any];account:[]}>();watch(profile,v=>emit('profile',v),{deep:true});
let platform='web';
// #ifdef APP-PLUS
platform=uni.getSystemInfoSync().platform==='ios'?'ios':'android';
// #endif
const captcha=ref<CaptchaInput>({}),captchaReady=ref(false),captchaRef=ref<InstanceType<typeof CaptchaField>>(),invite=ref(''),avatarOpen=ref(false);let alive=true,pendingRefresh=false;
async function run(action:(verify:()=>void,recapture:()=>void)=>Promise<void>){if(busy.value||!alive)return;let current=captureMemberContext();const verify=()=>{if(!alive)throw new Error('页面已关闭。');current();};const recapture=()=>{current=captureMemberContext();verify();};busy.value=true;message.value='';try{await action(verify,recapture);}catch(e){try{verify();message.value=(e as Error).message;}catch{}}finally{if(alive){busy.value=false;if(pendingRefresh){pendingRefresh=false;void refresh();}}}}
async function refresh(){await run(async verify=>{const result=await memberApi.config();verify();config.value=result;if(uni.getStorageSync('hetun-member-token')){const value=await memberApi.profile();verify();profile.value=value.profile;}else profile.value=null;if(config.value.configured&&!props.accountOnly){const value=await memberApi.plans();verify();plans.value=value.groups||[];}});}
async function login(){if(!captchaReady.value)return;await run(async(verify,recapture)=>{try{
 if(register.value&&!applicationRuntime.registrationEnabled)throw new Error('当前站点已关闭注册。');
 const result=await memberApi.login(username.value,password.value,register.value,password2.value,captcha.value,invite.value.trim());
 recapture();password.value='';password2.value='';
 if(result.pending){register.value=false;message.value='注册已提交，账号需要管理员审核，审核通过后再登录。';return;}
 if(!result.profile)throw new Error('未收到账号信息，请重新登录。');
 profile.value=result.profile;if(!props.accountOnly){const value=await memberApi.plans();verify();plans.value=value.groups||[];}message.value='已登录苹果 CMS 账号。';
 }finally{if(alive)void captchaRef.value?.refresh();}});}
watch(()=>applicationRuntime.registrationEnabled,v=>{if(!v)register.value=false;});
function pointsPrice(group:any){return applicationRuntime.membership.managed?Number(applicationRuntime.membership[period.value as 'day'|'week'|'month'|'year']):Number(group['group_points_'+period.value]||0);}
function openExternal(url:string){if(!/^https?:\/\//i.test(url))return;
 // #ifdef H5
 window.open(url,'_blank','noopener,noreferrer');
 // #endif
 // #ifdef APP-PLUS
 plus.runtime.openURL(url);
 // #endif
}
function copy(value:string){const current=captureMemberContext();const feedback=(text:string)=>{if(!alive)return;try{current();message.value=text;}catch{}};if(value)uni.setClipboardData({data:value,success:()=>feedback('已复制。'),fail:()=>feedback('复制失败，请重试。')});}
async function inviteFriend(){await run(async verify=>{const v=await applicationApi.invitation();verify();copy(v.text||v.code);});}
function contact(){if(applicationRuntime.share.contactMode==='link')openExternal(applicationRuntime.share.contactUrl);else copy(applicationRuntime.share.contactText);}
async function setAvatar(url:string){await run(async verify=>{verify();await applicationApi.avatar({url});verify();const value=await memberApi.profile();verify();profile.value=value.profile;avatarOpen.value=false;message.value='头像已更新。';});}
async function uploadAvatar(){await run(async verify=>{
 const selected=await new Promise<UniApp.ChooseImageSuccessCallbackResult>((resolve,reject)=>uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['album'],success:resolve,fail:()=>reject(new Error('未选择图片。'))}));
 verify();const file=Array.isArray(selected.tempFiles)?selected.tempFiles[0]:undefined;if(file&&file.size>1024*1024)throw new Error('请选择不超过 1 MB 的 PNG 或 JPEG 图片。');
 let encoded='';
 // #ifdef H5
 const blob=await (await fetch(selected.tempFilePaths[0])).blob();if(blob.size>1024*1024)throw new Error('头像不能超过 1 MB。');
 encoded=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('图片读取失败。'));reader.readAsDataURL(blob);});
 // #endif
 // #ifdef APP-PLUS
 encoded=await new Promise<string>((resolve,reject)=>plus.io.resolveLocalFileSystemURL(selected.tempFilePaths[0],entry=>{if(!entry.isFile){reject(new Error('请选择图片文件。'));return;}(entry as unknown as PlusIoFileEntry).file(file=>{if((file.size||0)>1024*1024){reject(new Error('头像不能超过 1 MB。'));return;}const reader=new plus.io.FileReader();reader.onloadend=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('图片读取失败。'));reader.readAsDataURL(file);},()=>reject(new Error('图片读取失败。')));},()=>reject(new Error('无法读取所选图片。'))));
 // #endif
 verify();const data=encoded.split(',')[1];if(!data)throw new Error('当前环境无法读取图片。');
 await applicationApi.avatar({data});verify();const value=await memberApi.profile();verify();profile.value=value.profile;avatarOpen.value=false;message.value='头像已更新。';
 });}
watch(()=>getHistoryScope(),()=>{profile.value=null;orders.value=[];pending.value=null;payUrl.value='';qrRows.value=[];plans.value=[];config.value={};avatarOpen.value=false;message.value='';if(busy.value)pendingRefresh=true;else void refresh();},{flush:'sync'});
onBeforeUnmount(()=>{alive=false;});
async function logout(){await run(async(_verify,recapture)=>{await memberApi.logout();recapture();profile.value=null;orders.value=[];pending.value=null;payUrl.value='';qrRows.value=[];});}
async function showOrders(){mode.value='orders';await run(async verify=>{const value=await memberApi.orders();verify();orders.value=value.orders;});}
async function purchase(id:number,points=false){await run(async verify=>{if(platform==='ios'&&!points)throw new Error('iOS 内购尚未配置，当前无法在 App 内购买会员。');const result=points?await memberApi.upgrade(id,period.value):await memberApi.purchase(id,period.value,platform);verify();pending.value=points?null:result.order;payUrl.value='';qrRows.value=[];message.value=points?'升级结果已由 CMS 确认。':'订单已由 CMS 创建，支付结果需要点击订单查询确认。';const value=await memberApi.profile();verify();profile.value=value.profile;});}
async function recharge(){await run(async verify=>{if(platform==='ios')throw new Error('iOS 内购尚未配置。');const v=await memberApi.recharge(Number(amount.value),platform);verify();pending.value=v.order;payUrl.value='';qrRows.value=[];message.value='充值订单已创建，支付完成后请查询订单状态。';});}
async function check(code:string){await run(async verify=>{const result=await memberApi.order(code);verify();message.value=Number(result.order.order_status)===1?'CMS 已确认支付成功。':'CMS 尚未确认支付。';const list=await memberApi.orders();verify();orders.value=list.orders;const value=await memberApi.profile();verify();profile.value=value.profile;});}
async function checkout(order=pending.value){await run(async verify=>{if(platform==='ios')throw new Error('iOS 内购尚未配置。');pending.value=order;payUrl.value='';qrRows.value=[];const v=await memberApi.checkout(Number(order.order_id),order.order_code,payMethod.value,platform);verify();if(v.kind==='qrcode'){const m=QR.create(v.code,{errorCorrectionLevel:'M'}).modules;qrRows.value=Array.from({length:m.size},(_,r)=>Array.from({length:m.size},(_,c)=>!!m.get(r,c)));message.value='请使用相应支付 App 扫描二维码，完成后查询 CMS 订单状态。';}else {payUrl.value=v.checkoutPath?getServiceBase()+v.checkoutPath:v.url;message.value='收银台已准备，请点击前往付款。';}});}
function payment(){if(!payUrl.value)return;
// #ifdef H5
window.open(payUrl.value,'_blank','noopener,noreferrer');
// #endif
// #ifdef APP-PLUS
plus.runtime.openURL(payUrl.value);
// #endif
}
onMounted(refresh);
</script>
<template><view class="member-panel" :class="{'account-only':accountOnly}"><view v-if="!accountOnly" class="member-channel-tabs"><text :class="{active:mode==='account'}" @click="mode='account'">精选</text><text @click="profile?mode='account':emit('account')">会员套餐</text><text :class="{active:mode==='orders'}" @click="profile?showOrders():emit('account')">我的订单</text><text :class="{active:mode==='recharge'}" @click="profile?mode='recharge':emit('account')">积分充值</text></view><view class="member-head" :class="{'account-head':accountOnly}"><text v-if="!accountOnly" class="vip-crest">V</text><view class="member-person" @click="!profile&&emit('account')"><view class="member-avatar"><image v-if="profile?.user_portrait" :src="assetUrl(profile.user_portrait)" mode="aspectFill"/><text v-else-if="profile">{{String(profile.user_name||'用户').slice(0,1)}}</text><PufferMark v-else :size="29" color="#27c9e3"/></view><view><text class="member-title">{{profile?.user_name||(accountOnly?'账号登录':'登录 / 注册')}}</text><text class="member-caption">{{accountOnly?'管理你的苹果 CMS 账号':profile?.member_name||'会员专属权益'}}</text></view></view><template v-if="!accountOnly"><view class="renewal-line"><text>{{profile?.member_name||'VIP 会员'}}<text class="renewal-subtitle"> {{profile?.expire_date?'到期 '+profile.expire_date:'选择适合你的会员套餐'}}</text></text></view><button class="renewal-button" @click="profile?mode='account':emit('account')">{{profile?'立即续费':'登录后开通会员'}}</button></template><text v-else-if="profile">积分 {{profile.user_points}} · 用户组 {{profile.group_id}}</text></view><view v-if="!accountOnly" class="membership-facts"><text class="facts-title">我的专享权益</text><view class="facts-grid"><view><text>会员身份</text><text>{{profile?.member_name||'登录后查看'}}</text></view><view><text>会员有效期</text><text>{{profile?.expire_date||'以 CMS 账户为准'}}</text></view><view><text>账户积分</text><text>{{profile?.user_points??'登录后查看'}}</text></view></view></view><view class="message" v-if="message">{{message}}</view><view v-if="!config.configured" class="message">尚未连接苹果 CMS。连接后可使用原账号登录和会员套餐。</view><view v-if="!profile&&accountOnly" class="login"><input v-model="username" name="cms-account" autocomplete="off" placeholder="苹果 CMS 账号"/><input v-model="password" name="cms-password" autocomplete="new-password" password placeholder="密码"/><input v-if="register" v-model="password2" password placeholder="再次输入密码"/><input v-if="register&&applicationRuntime.share.invite" v-model="invite" placeholder="邀请码（选填）"/><CaptchaField ref="captchaRef" v-model="captcha" :action="register?'register':'login'" :disabled="busy" :demo="demo" @ready="captchaReady=$event"/><button :disabled="busy||!config.configured||!captchaReady" @click="login">{{busy?'处理中…':register?'提交注册':'登录'}}</button><text v-if="applicationRuntime.registrationEnabled||register" @click="!busy&&(register=!register)">{{register?'已有账号，去登录':'注册新账号'}}</text></view><view v-else-if="accountOnly" class="account-controls"><text>已登录 {{profile.user_name}}</text><button v-if="applicationRuntime.avatar.upload||applicationRuntime.avatar.library.length" :disabled="busy" @click="avatarOpen=!avatarOpen">更换头像</button><view v-if="avatarOpen" class="avatar-picker"><view class="avatar-options"><image v-for="url in applicationRuntime.avatar.library" :key="url" :src="assetUrl(url)" mode="aspectFill" role="button" aria-label="选择头像" @click="!busy&&setAvatar(url)"/></view><button v-if="applicationRuntime.avatar.upload" :disabled="busy" @click="uploadAvatar">上传头像（PNG / JPEG，1 MB 以内）</button></view><button :disabled="busy" @click="logout">退出登录</button></view><template v-else-if="profile"><view class="member-tabs"><text @click="mode='account'">会员套餐</text><text @click="showOrders">我的订单</text><text @click="mode='recharge'">积分充值</text><text @click="logout">退出</text></view><template v-if="mode==='account'"><view class="periods"><text v-for="p in [{id:'day',name:'天'},{id:'week',name:'周'},{id:'month',name:'月'},{id:'year',name:'年'}]" :key="p.id" :class="{chosen:period===p.id}" @click="period=p.id">{{p.name}}套餐</text></view><view v-if="!plans.length" class="message">CMS 未返回可购买套餐，请检查站点的会员组及升级设置。</view><view v-for="g in plans" :key="g.group_id" class="plan"><text>{{g.group_name}}</text><text>现金 ¥{{g['price_'+period]??'未配置'}} / 积分 {{pointsPrice(g)||'未配置'}}</text><button :disabled="busy||platform==='ios'||!Number(g['price_'+period])" @click="purchase(Number(g.group_id))">购买 / 续费</button><button :disabled="busy||!pointsPrice(g)" @click="purchase(Number(g.group_id),true)">CMS 积分升级</button></view></template><view v-else-if="mode==='recharge'" class="login"><text>充值金额由 CMS 再次校验并按站点比例兑换积分</text><input v-model.number="amount" type="number"/><button :disabled="busy||platform==='ios'" @click="recharge">创建充值订单</button></view><template v-else><view v-if="!orders.length" class="message">暂无订单</view><view v-for="o in orders" :key="o.order_code" class="plan"><text>{{o.order_code}}</text><text>¥{{o.order_price}} · {{Number(o.order_status)===1?'已支付':'待支付'}}</text><button v-if="Number(o.order_status)===0" :disabled="busy||platform==='ios'" @click="pending=o">选择此订单付款</button><button :disabled="busy" @click="check(o.order_code)">查询 CMS 支付状态</button></view></template><view v-if="pending" class="message"><text>订单 {{pending.order_code}} · ¥{{pending.order_price}}</text><view class="payment-methods"><text v-for="m in [{id:'alipay',name:'支付宝'},{id:'weixin',name:'微信'},{id:'epay',name:'易支付'},{id:'codepay',name:'码支付'},{id:'zhapay',name:'Z 支付'}]" :key="m.id" :class="{chosen:payMethod===m.id}" @click="payMethod=m.id;payUrl='';qrRows=[]">{{m.name}}</text></view><button :disabled="busy||platform==='ios'" @click="checkout()">生成 CMS 收银台</button><text>可用支付渠道以 CMS 配置为准。</text><view v-if="qrRows.length" class="qr"><view v-for="(row,r) in qrRows" :key="r" class="qr-row"><view v-for="(dark,c) in row" :key="c" class="qr-cell" :style="{background:dark?'#000':'#fff'}"/></view></view><button v-if="payUrl" @click="payment">前往付款</button><button :disabled="busy" @click="check(pending.order_code)">查询此订单状态</button></view></template><view v-if="accountOnly" class="account-extras"><button v-if="applicationRuntime.share.text" @click="copy(applicationRuntime.share.text)">分享应用</button><button v-if="profile&&applicationRuntime.share.invite" :disabled="busy" @click="inviteFriend">邀请好友</button><button v-if="applicationRuntime.share.contactText||applicationRuntime.share.contactUrl" @click="contact">联系我们</button><button v-if="applicationRuntime.tvDownloadUrl" @click="openExternal(applicationRuntime.tvDownloadUrl)">打开 TV 端下载地址</button></view><text class="footnote" v-if="platform==='ios'&&!accountOnly">iOS 内购等待配置 Apple 商品及服务端凭据。</text></view></template>
