0 24px;overflow:visible;gap:0}.member-person{display:flex;align-items:center;gap:10px;position:relative;z-index:1}.member-avatar{height:40px;width:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#f4d6bc,#c397b4);color:#fff;font-size:22px}.member-title{font-size:15px;font-weight:500}.member-caption{display:block;font-size:11px;color:#a88cbd;margin-top:5px}.vip-crest{position:absolute;right:5px;top:-21px;width:64px;height:64px;box-sizing:border-box;font-size:42px;line-height:64px;text-align:center;font-style:italic;font-weight:900;color:#efc9ff;transform:rotate(-8deg);background:linear-gradient(140deg,#1b1436,#7131d2 65%,#dbcc8c);clip-path:polygon(21% 0,77% 0,100% 38%,51% 100%,0 38%);text-shadow:2px 3px #29133c}.renewal-line{margin:25px 0 12px;font-size:14px;color:#fff}.renewal-subtitle{font-size:12px}.renewal-button{width:100%;background:linear-gradient(100deg,#d5b3f4,#fae3b7)!important;border-radius:4px!important;color:#201126!important;font-size:14px!important;line-height:37px!important;margin:0!important;padding:0!important}.membership-facts{margin:12px 0 25px}.facts-title{display:block;font-size:15px;margin-bottom:10px}.facts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.facts-grid>view{padding:13px 10px;background:var(--surface);border-radius:3px;min-width:0}.facts-grid>view>text:first-child{display:block;font-size:13px}.facts-grid>view>text:last-child{display:block;font-size:10px;color:#ad9a77;margin-top:8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.account-only{padding:16px}.account-head{min-height:0;background:var(--surface);color:var(--text);margin:0 0 15px}.account-head .member-caption{color:var(--muted)}.account-controls{padding:16px 0;font-size:13px}.login input{border-color:#80808044;color:var(--text)}.login>text{color:var(--muted)}.plan{border-color:#80808033}.member-tabs{flex-wrap:wrap}.member-tabs>text{cursor:pointer}.member-gold .member-head{background:linear-gradient(135deg,#514330,#292018)}
</style>